// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Crawl live site read-only, store named controls, report gaps
// Flo: open the dashboard home > collect same-site links > visit each (GET only) > read the accessibility tree > write map-report.txt > then per job: are its labels on its page? > OK or GAP > summary
// I/O: Ctx (caller) > rows in the state db (mapz), <stat>/map-report.txt, lines on stdout; counts of pages, controls, ok, gaps
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const pack = @import("ut-loca-pack.zig"); const priv = @import("ru-safe-priv.zig"); const fld = @import("ut-text-fold.zig");
const CF = .{ .maxn = 800, .maxr = 40, .file = "map-report.txt", .skip = [_][]const u8{ "logout", "signout", "sign-out", "log-out", "delete", "cancel", "unsubscribe" }, .links = "Array.from(document.querySelectorAll('a[href]')).map(function(a){return a.getAttribute('href')+'\\t'+(a.innerText||a.getAttribute('aria-label')||'').trim().slice(0,40)})", .titl = "document.title" };
pub const Sum = struct { pages: u32 = 0, controls: u32 = 0, okay: u32 = 0, gaps: u32 = 0, routes: u32 = 0 };
const Row = struct { role: []const u8, name: []const u8 };
fn valOf(valu: ?std.json.Value) []const u8 { const vv = valu orelse return ""; if (vv != .object) return ""; const inn = vv.object.get("value") orelse return ""; return if (inn == .string) inn.string else ""; }
fn axRows(ctx: *task.Ctx) ![]const Row { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const res = try ctx.page.call(ctx.aren, "Accessibility.getFullAXTree", ""); const nodes = res.object.get("nodes") orelse return error.CdpError; var out: std.ArrayList(Row) = .empty; for (nodes.array.items) |nod| { if (out.items.len >= CF.maxn) break; if (nod != .object) continue; if (nod.object.get("ignored")) |ign| { if (ign == .bool and ign.bool) continue; } const nam = valOf(nod.object.get("name")); if (nam.len == 0) continue; try out.append(ctx.aren, .{ .role = valOf(nod.object.get("role")), .name = try priv.redact(ctx.aren, nam) }); } return out.items; }
fn onPage(ctx: *task.Ctx, rows: []const Row, labs: []const []const u8) !bool { var all: std.ArrayList(u8) = .empty; for (rows) |rw| { try all.appendSlice(ctx.aren, rw.name); try all.append(ctx.aren, '\n'); } return fld.matchAny(ctx.aren, all.items, labs); }
fn seen(list: []const []const u8, path: []const u8) bool { for (list) |ite| { if (std.mem.eql(u8, ite, path)) return true; } return false; }
fn skipLink(path: []const u8) bool { for (CF.skip) |wrd| { if (std.ascii.findIgnoreCase(path, wrd) != null) return true; } return false; }
fn routeOf(href: []const u8) ?[]const u8 { if (href.len == 0 or href[0] != '/' or (href.len > 1 and href[1] == '/')) return null; var end: usize = href.len; for (href, 0..) |chr, ix| { if (chr == '?' or chr == '#') { end = ix; break; } } return href[0..end]; }
fn linkList(ctx: *task.Ctx) ![]const []const u8 { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const val = try ctx.page.evalVal(ctx.aren, CF.links); var out: std.ArrayList([]const u8) = .empty; if (val != .array) return out.items; for (val.array.items) |ite| { if (ite != .string) continue; const tab = std.mem.findScalar(u8, ite.string, '\t') orelse ite.string.len; const rte = routeOf(ite.string[0..tab]) orelse continue; if (skipLink(rte) or seen(out.items, rte)) continue; try out.append(ctx.aren, rte); } return out.items; }
fn note(ctx: *task.Ctx, rep: *std.ArrayList(u8), path: []const u8, rows: []const Row) !void { const fin = ctx.page.urlNow(ctx.aren) catch ""; const ttl = ctx.page.evalStr(ctx.aren, CF.titl) catch ""; try rep.print(ctx.aren, "\n## {s}  (final: {s})  title: {s}  controls: {d}\n", .{ path, fin, ttl, rows.len }); for (rows) |rw| try rep.print(ctx.aren, "{s} | {s}\n", .{ rw.role, rw.name }); }
fn save(ctx: *task.Ctx, rep: []const u8) void { const path = std.fs.path.join(ctx.aren, &.{ ctx.statd, CF.file }) catch return; std.Io.Dir.cwd().writeFile(ctx.iozz, .{ .sub_path = path, .data = rep }) catch {}; }
fn visitRows(ctx: *task.Ctx, sum: *Sum, rep: *std.ArrayList(u8), url: []const u8, key: []const u8) ?[]const Row { task.visit(ctx, url) catch |err| { task.say(ctx, "GAP     page {s}: {s}", .{ key, @errorName(err) }); sum.gaps += 1; return null; }; const rows = axRows(ctx) catch |err| { task.say(ctx, "GAP     page {s}: {s}", .{ key, @errorName(err) }); sum.gaps += 1; return null; }; sum.pages += 1; sum.controls += @intCast(rows.len); ctx.store.mapClear(key) catch {}; const now = task.nowMs(ctx); for (rows) |rw| ctx.store.mapAdd(key, rw.role, rw.name, now) catch {}; note(ctx, rep, key, rows) catch {}; return rows; }
fn discover(ctx: *task.Ctx, sum: *Sum, rep: *std.ArrayList(u8)) !void { const home = try std.fmt.allocPrint(ctx.aren, "{s}/", .{ctx.conf.base_appz_main}); _ = visitRows(ctx, sum, rep, home, "/") orelse return; const links = try linkList(ctx); task.say(ctx, "routes found on the home page: {d}", .{links.len}); var seenr: std.ArrayList([]const u8) = .empty; for (links) |rte| { if (seenr.items.len >= CF.maxr) break; if (std.mem.eql(u8, rte, "/")) continue; try seenr.append(ctx.aren, rte); sum.routes += 1; task.say(ctx, "ROUTE   {s}", .{rte}); const url = try std.fmt.allocPrint(ctx.aren, "{s}{s}", .{ ctx.conf.base_appz_main, rte }); _ = visitRows(ctx, sum, rep, url, rte); save(ctx, rep.items); } }
pub fn mapRun(ctx: *task.Ctx) !Sum { const prev = ctx.auth; ctx.auth = true; defer ctx.auth = prev; var sum: Sum = .{}; var rep: std.ArrayList(u8) = .empty; try rep.appendSlice(ctx.aren, "# or-orac-webs map report (read-only crawl; names are redacted)\n"); discover(ctx, &sum, &rep) catch |err| task.say(ctx, "GAP     discovery: {s}", .{@errorName(err)}); save(ctx, rep.items); var done: std.ArrayList([]const u8) = .empty; for (&jobs.JOBS) |*jb| { if (jb.path.len == 0) continue; const path = try jrun.pathOf(ctx, jb, .{}); if (seen(done.items, path)) continue; try done.append(ctx.aren, path); const rows = visitRows(ctx, &sum, &rep, path, path) orelse continue; for (&jobs.JOBS) |*other| { if (other.path.len == 0) continue; const opath = try jrun.pathOf(ctx, other, .{}); if (!std.mem.eql(u8, opath, path)) continue; for (other.steps) |tpl| { if (tpl.key.len == 0 or tpl.op == .expect) continue; const labs = pack.lab(ctx.conf, tpl.key); if (try onPage(ctx, rows, labs)) { sum.okay += 1; } else { sum.gaps += 1; task.say(ctx, "GAP     {s}: {s} not on {s}", .{ other.name, tpl.key, path }); } } } } save(ctx, rep.items); task.say(ctx, "map: {d} pages, {d} routes, {d} controls, {d} ok, {d} gaps · report: {s}", .{ sum.pages, sum.routes, sum.controls, sum.okay, sum.gaps, CF.file }); return sum; }
